mapper.select:
SELECT o.*, p.title AS product_title, p.image_url AS product_image_url,
       b.nickname AS buyer_nickname, s.nickname AS seller_nickname
FROM `order` o
LEFT JOIN product p ON o.product_id = p.id
LEFT JOIN user b ON o.buyer_id = b.id
LEFT JOIN user s ON o.seller_id = s.id

    AND (o.buyer_id = #{userId} OR o.seller_id = #{userId})
    AND o.buyer_id = #{buyerId}
    AND o.seller_id = #{sellerId}
    AND o.status = #{status}

ORDER BY o.create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM `order` o

    AND (o.buyer_id = #{userId} OR o.seller_id = #{userId})
    AND o.buyer_id = #{buyerId}
    AND o.seller_id = #{sellerId}
    AND o.status = #{status}
